const natureTasks = [
  `Plant at least two native trees in your neighbourhood, school, or garden. Before planting, research which tree species naturally grow in your region and are suitable for the available space. Ask someone experienced about proper planting techniques and watering requirements. Make sure the trees have enough sunlight and room to grow. Take responsibility for watering them regularly, especially during hot weather. Avoid damaging existing plants while preparing the soil. Add a small protective fence if necessary. Take photographs of your planting activity and observe the trees every month. Your goal is not simply to plant trees but to help them survive and grow into healthy habitats for wildlife.`,

  `Organise a neighbourhood cleanliness drive focused on collecting litter from public spaces. Invite friends, classmates, or family members to participate. Choose a safe location such as a nearby park, playground, or community garden. Carry reusable gloves and separate bags for recyclable and non-recyclable waste. Never touch broken glass, medical waste, chemicals, or unidentified dangerous objects. Inform the appropriate authorities about hazardous materials. After collecting the litter, ensure everything reaches suitable waste collection facilities. Take before-and-after photographs to document your efforts. Encourage participants to discuss why littering harms animals, plants, and local ecosystems, and motivate everyone to keep public spaces clean.`,

  `Start a personal plastic reduction challenge for seven consecutive days. Avoid unnecessary single-use plastic items such as disposable cups, straws, shopping bags, and packaging whenever practical. Carry a reusable water bottle and cloth shopping bag instead. Observe how much plastic you normally use and identify situations where alternatives are available. Encourage your family members to participate without pressuring anyone. Research local recycling options for plastic materials that cannot be avoided. Maintain a daily record of your progress and challenges. At the end of the week, calculate which habits were easiest to change and continue those improvements as part of your everyday lifestyle.`,

  `Create a small bird-friendly corner in your garden, balcony, or suitable outdoor area. Place a shallow container of clean water somewhere safe and accessible to birds. Refill it regularly and clean the container frequently to prevent contamination. If local conditions permit, grow native flowering plants or shrubs that provide natural food and shelter. Keep the area away from pets and other potential disturbances. Avoid feeding birds processed human food or bread. Research which bird species naturally occur in your region and observe their behaviour from a respectful distance. Record your observations in a notebook and encourage others to protect local bird populations.`,

  `Conduct a household electricity conservation audit with your family. Observe which lights, fans, chargers, televisions, and other electrical appliances are unnecessarily switched on. Identify simple opportunities to reduce electricity consumption without compromising safety or comfort. Switch off unused lights and unplug chargers when appropriate. Make better use of natural daylight during daytime hours. Discuss efficient appliance usage with family members and create a simple daily checklist. Record electricity meter readings if your household permits it. Compare your observations over several weeks. Explain how reducing unnecessary electricity consumption can lower environmental impacts associated with energy production and encourage everyone to develop responsible energy habits.`,

  `Organise a paper-saving campaign at your school or workplace. Examine how paper is currently used for notes, announcements, assignments, and printing. Encourage people to use both sides of sheets whenever appropriate. Reuse partially used notebooks for rough work and maintain a separate collection for recyclable paper. Suggest digital notices where they are practical and accessible. Create informative posters explaining how responsible paper consumption helps reduce pressure on forests and resources. Make sure important accessibility needs are considered before replacing printed materials. Monitor the amount of paper collected for recycling and share the results with participants at the end of the campaign.`,

  `Spend one day observing the plants and animals in a nearby green space. Visit a safe public garden, park, or natural area with permission where required. Look carefully for different plant species, insects, birds, and other living organisms. Record your observations without disturbing or collecting anything. Avoid touching unknown plants, nests, eggs, or wild animals. Photograph interesting discoveries from a respectful distance. Research the ecological roles of at least three organisms you observed. Notice how different species depend on one another for food, shelter, and survival. Share your findings with friends to increase awareness about biodiversity and the importance of protecting local ecosystems.`,

  `Prepare a household water conservation plan. Observe how water is used while brushing teeth, washing dishes, bathing, watering plants, and cleaning. Identify activities where water is unnecessarily wasted and suggest practical improvements to your family. Turn off taps when water is not needed and report leaking taps to the responsible person. Consider collecting suitable rainwater for gardening where local rules and safety conditions permit. Never store untreated water for drinking. Create a simple chart showing your family's water-saving habits. Review the chart after one week and identify which improvements have become regular habits. Explain why freshwater conservation is important for communities, agriculture, wildlife, and future generations.`,

  `Design an awareness poster explaining the dangers of deforestation. Research how forests support biodiversity, regulate climate, protect soil, and contribute to the water cycle. Include examples of animals and plants that depend on forest habitats. Explain how excessive tree removal can affect nearby communities and increase environmental problems. Use original illustrations, simple diagrams, and clear messages instead of copying existing posters. Display your finished poster in an appropriate community or educational space with permission. Ask viewers to suggest practical ways of supporting forest conservation. Your objective is to communicate accurate environmental information in a visually interesting way that encourages responsible choices.`,

  `Start composting suitable biodegradable kitchen waste at home. Collect vegetable peels, fruit scraps, dry leaves, and other appropriate organic materials. Research a composting method suitable for your available space and climate. Avoid adding plastic, glass, meat, dairy products, or other unsuitable materials to a basic compost container. Maintain an appropriate balance of dry and moist materials and allow enough airflow. Observe the mixture regularly and follow proper hygiene practices. When the compost is ready, use it for suitable garden plants. Keep a record of the organic waste diverted from ordinary rubbish and explain how composting supports healthier soil and reduces waste.`,

  `Create a small pollinator-friendly garden using native flowering plants. Research which locally suitable flowers provide nectar and pollen for bees, butterflies, and other pollinating insects. Select plants that flower during different parts of the year whenever possible. Avoid using harmful pesticides and chemical treatments. Provide a shallow water source with safe landing surfaces, and ensure the area remains suitable for insects. Observe visiting pollinators without disturbing them. Record the different species you notice and investigate their importance in plant reproduction and food production. Share your garden design with neighbours and encourage them to create additional pollinator-friendly spaces in their communities.`,

  `Conduct a plastic waste investigation in your household for three days. Observe the packaging and disposable plastic items entering your home through groceries, deliveries, personal care products, and other purchases. Do not collect dirty or hazardous waste unnecessarily. Instead, record the types and approximate quantities of plastic you notice. Identify products that have reusable, refillable, or less-packaged alternatives. Discuss practical substitutions with your family and consider local recycling facilities. Create a short report describing your findings and recommendations. Explain how thoughtful purchasing decisions can reduce unnecessary waste while recognising that recycling systems differ between communities and not every plastic item is recyclable.`,

  `Organise a responsible nature photography activity in a nearby park or garden. Photograph plants, insects, birds, trees, and other natural features without disturbing their habitats. Do not approach nests, chase animals, break branches, or remove flowers. Use your photographs to identify species through reliable educational resources. Create a small digital collection showing the biodiversity present in your neighbourhood. Add accurate captions explaining why each organism or habitat matters. Share the collection with friends or classmates to encourage appreciation of local nature. Include a reminder that wildlife photography should always prioritise animal safety and habitat protection over obtaining an impressive photograph.`,

  `Encourage your family to adopt reusable shopping habits. Check which disposable bags, containers, and packaging materials are commonly brought home during shopping trips. Prepare a collection of clean reusable cloth bags and suitable containers for future purchases. Keep them somewhere convenient so they are easy to remember. Explain why reusable products can reduce demand for disposable materials when used repeatedly. Research nearby shops that offer refill options or reduced packaging. Avoid purchasing unnecessary replacements for reusable items that are already working properly. After two weeks, review whether your family's shopping habits have changed and identify additional realistic opportunities to reduce waste.`,

  `Research endangered animal species found in your country and prepare an educational information sheet about one of them. Include its natural habitat, diet, ecological importance, major threats, and conservation efforts. Use trustworthy scientific or wildlife conservation sources instead of relying on unverified social media posts. Explain how habitat destruction, pollution, illegal wildlife trade, and climate change can threaten animal populations. Include practical actions ordinary citizens can take to support conservation, such as protecting habitats and avoiding products associated with wildlife exploitation. Present your findings in simple language and share them with classmates or family members to increase awareness about biodiversity.`,

  `Plan a community campaign encouraging people to keep rivers, lakes, and ponds clean. Research common sources of freshwater pollution, including plastic litter, untreated sewage, agricultural runoff, and industrial waste. Prepare informative posters explaining how polluted water affects fish, birds, plants, and human communities. Never enter unsafe water bodies or attempt to handle unknown waste. Instead, identify responsible local authorities and explain how residents can report pollution. Encourage people to avoid throwing rubbish into drains and waterways. Share practical water protection tips through an appropriate community noticeboard or school presentation. Focus on prevention and responsible reporting rather than unsafe cleanup activities.`,

  `Spend a week tracking your use of disposable food packaging. Record how often you receive plastic wrappers, disposable cups, takeaway containers, and other single-use materials. Look for opportunities to carry reusable lunch containers and request minimal packaging where practical. Discuss sustainable purchasing options with your family. Consider preparing homemade snacks using ingredients stored in reusable containers. Do not waste edible food merely to avoid packaging. At the end of the week, compare your observations and identify which changes were convenient and affordable. Write a short reflection about how everyday food choices influence packaging waste and how households can reduce unnecessary environmental pressure.`,

  `Build a simple educational display about the importance of wetlands. Research how wetlands provide habitats for birds, fish, amphibians, insects, and aquatic plants. Explain their role in storing water, supporting biodiversity, and reducing the effects of certain floods. Include examples of local wetlands where reliable information is available. Create an illustrated diagram showing the relationships between water, soil, vegetation, and wildlife. Discuss common threats such as drainage, pollution, construction, and invasive species. Present your display in a classroom or community space with permission. Encourage viewers to understand wetlands as valuable ecosystems rather than empty land available for development.`,

  `Encourage responsible waste separation in your home. Research the waste collection categories accepted by your local municipality or recycling service. Set up clearly labelled containers for suitable dry recyclables, wet biodegradable waste, and general rubbish. Keep hazardous materials, batteries, electronic waste, and chemicals separate according to local disposal instructions. Explain the system to everyone in your household. Monitor whether materials are being sorted correctly and make adjustments when confusion occurs. Avoid placing contaminated materials into recycling containers. After one week, evaluate how much easier waste management has become and share useful lessons with neighbours who may want to introduce a similar system.`,

  `Research the environmental benefits of protecting mangrove forests. Learn how mangroves provide nursery habitats for marine species, support coastal biodiversity, store carbon, and help reduce coastal erosion. Find examples of mangrove ecosystems in your country and identify threats affecting them. Create a short educational presentation using maps, photographs, and factual explanations. Explain why planting trees in unsuitable coastal locations is not a replacement for protecting existing natural ecosystems. Share practical conservation actions, such as supporting habitat protection and avoiding pollution of coastal waters. Encourage your audience to recognise the ecological and community benefits of preserving healthy mangrove environments.`,

  `Start a personal eco-friendly transportation challenge. For one week, observe how you travel to school, work, shops, or nearby destinations. Identify short journeys that could safely be completed by walking, cycling, or using public transportation with appropriate supervision and road safety precautions. Avoid unnecessary vehicle trips where practical. Record the distance and transportation method for each journey. Discuss accessibility, weather, safety, and convenience before changing travel habits. Research how shared transportation and active travel can reduce emissions when they replace individual vehicle journeys. At the end of the week, write down which alternatives were practical and how they could become regular habits.`,

  `Create a small herb garden using suitable containers and locally appropriate plants. Choose herbs such as mint, coriander, basil, or other species that grow well in your climate. Reuse clean containers only when they are safe for growing plants and provide suitable drainage. Use appropriate soil and sunlight conditions for each herb. Water carefully instead of flooding the containers. Avoid unnecessary chemical pesticides and research natural garden care methods. Observe how the plants grow over several weeks and record their requirements. Explain how growing some household herbs can encourage an appreciation of plants, responsible resource use, and small-scale urban gardening.`,

  `Investigate how food waste affects the environment. Research how wasted food represents unnecessary use of agricultural land, water, energy, transportation, and packaging. Observe how much edible food is discarded in your household over several days without touching unsafe waste. Identify common reasons, such as overbuying, forgotten leftovers, or poor meal planning. Suggest practical solutions including shopping lists, sensible portion sizes, proper storage, and using suitable leftovers. Never eat food that may be spoiled or unsafe. Create an informative family guide explaining how thoughtful food management can reduce waste and help households use their resources more responsibly.`,

  `Create a wildlife-friendly awareness campaign about protecting butterflies. Research the butterfly species found in your region, their life cycles, food sources, and preferred habitats. Explain why caterpillars need suitable host plants and adult butterflies need flowering plants. Encourage residents to grow native vegetation and avoid harmful pesticide use. Create original drawings showing the different stages of butterfly development. Share your educational material through a classroom display or community noticeboard with permission. If possible, observe butterflies in a nearby garden and record their visits without catching them. Emphasise that protecting habitats is more effective than simply collecting or displaying individual butterflies.`,

  `Prepare an environmental awareness presentation about air pollution. Research common sources such as vehicle exhaust, industrial emissions, construction dust, and the burning of waste. Explain how polluted air can affect ecosystems, visibility, and public health. Include practical prevention measures such as avoiding waste burning, supporting cleaner transportation, maintaining suitable green spaces, and following local pollution control guidance. Use trustworthy statistics and identify their sources. Create clear slides with diagrams and simple explanations rather than overwhelming viewers with technical information. Present your findings to classmates or family members and encourage them to discuss realistic actions that can improve local air quality.`,

  `Organise a reusable bottle awareness challenge among friends or classmates. Encourage participants to carry refillable water bottles instead of regularly purchasing disposable bottled water when safe drinking water is available. Explain how repeated reuse can reduce packaging waste and the demand for single-use bottles. Remind everyone to clean their bottles properly and refill them only from safe drinking water sources. Create a simple participation chart showing how many people adopted the habit. Avoid shaming anyone who cannot participate because of accessibility or water availability. At the end of the challenge, discuss what made the habit convenient and how it could continue throughout the year.`,

  `Learn about the environmental importance of soil conservation. Research how healthy soil supports plant growth, stores nutrients, holds water, and provides habitat for numerous organisms. Investigate common causes of soil degradation, including erosion, deforestation, excessive chemical use, and unsuitable agricultural practices. Create an illustrated diagram showing how vegetation protects soil from wind and rain. If you have access to a garden, observe differences between bare soil and soil covered with vegetation or mulch. Avoid digging up natural habitats. Prepare a short explanation of responsible gardening and land management practices that help maintain healthy soil for future generations.`,

  `Develop an educational campaign about reducing noise pollution in residential areas. Research how excessive noise can disturb people, birds, and other wildlife. Identify common sources such as unnecessary honking, loudspeakers, construction, and poorly managed machinery. Prepare a poster encouraging residents to follow local noise regulations and use sound-producing equipment responsibly. Explain why quiet green spaces are valuable for both humans and animals. Suggest practical measures such as avoiding unnecessary honking and keeping entertainment volumes appropriate. Share your campaign through a community group or school display with permission. Encourage people to respect the shared sound environment of their neighbourhood.`,

  `Create a simple rainwater awareness project. Research how rainwater harvesting systems collect and store rainfall for appropriate non-drinking uses such as gardening and cleaning. Draw a diagram showing how rooftop rainwater can travel through suitable gutters and filtration arrangements into a storage tank. Explain why storage containers must be maintained properly and protected from contamination and mosquitoes. Never suggest drinking untreated collected rainwater. Investigate whether rainwater harvesting is suitable for your local climate and building conditions. Present your design to your family and discuss whether a safe, practical system could be installed with help from qualified adults.`,

  `Research the environmental effects of electronic waste. Learn why discarded phones, computers, batteries, chargers, and household electronics require special handling. Explain how inappropriate disposal can release harmful substances and waste valuable recoverable materials. Create a list of authorised electronic waste collection or recycling facilities in your area using reliable local information. Encourage your family to repair functioning devices when practical and donate suitable working electronics through trustworthy programmes. Never dismantle batteries or electronic components yourself. Prepare an awareness poster explaining responsible disposal and the importance of keeping electronic waste separate from ordinary household rubbish.`,

  `Create a small native plant identification guide for your neighbourhood. Select ten plants that naturally occur in your region and research their common names, scientific names, appearance, and ecological roles. Use reliable botanical resources and photographs taken without damaging plants. Include information about which species support pollinators, provide shelter, or help maintain local biodiversity. Avoid collecting plants from protected areas. Arrange your findings into a colourful digital booklet or printed guide. Share it with friends, classmates, or gardening groups. Encourage people to recognise and appreciate native vegetation and choose locally suitable plants when developing gardens and community green spaces.`,

  `Conduct a personal environmental habits review. Spend three days observing your daily routines related to electricity, water, transport, food, packaging, and waste disposal. Record opportunities where you could make more environmentally responsible choices. Avoid setting unrealistic targets or making changes that compromise health, safety, or essential needs. Choose three practical habits to improve during the following week. Examples might include carrying reusable bags, switching off unnecessary lights, or reducing food waste. Maintain a simple progress diary and note any difficulties. At the end, reflect on how small consistent changes can contribute to broader environmental improvements when adopted by many people.`,

  `Prepare an awareness project about protecting coral reefs. Research how coral reefs support marine biodiversity and provide habitats for numerous ocean organisms. Learn about threats such as warming oceans, ocean acidification, pollution, and destructive fishing practices. Explain why corals are living organisms and why reef ecosystems require careful protection. Use photographs and diagrams from reliable educational sources. Suggest practical conservation actions such as reducing plastic waste, supporting responsible seafood choices, and respecting marine protected areas. Present your findings to classmates or family members. Make sure your project explains that coral reef protection requires both local conservation and broader action against climate change.`,

  `Encourage responsible clothing consumption within your family. Research how clothing production can require large amounts of water, energy, raw materials, and transportation. Examine your wardrobe and identify garments that remain useful but are rarely worn. Consider exchanging suitable clothing with family members, donating clean usable items through trustworthy organisations, or repairing minor damage. Avoid purchasing unnecessary new clothes simply because a trend changes. Learn about fabric care techniques that can help garments last longer. Create a short awareness message explaining how thoughtful purchasing, repairing, and reusing clothing can reduce textile waste and encourage more sustainable consumption habits.`,

  `Investigate the importance of protecting local grasslands. Research how grasslands provide habitats for grazing animals, insects, birds, and native plant species. Learn about the ecological role of grasses and how their root systems can help protect soil. Identify threats such as habitat conversion, overgrazing, invasive species, and unsuitable land management. Create a visual presentation showing why grasslands should not automatically be considered unused land. Include examples from your country where available. Share your presentation with classmates and encourage respect for open natural habitats. Emphasise the importance of science-based conservation and protecting native vegetation.`,

  `Organise a small environmental quiz for your friends or family. Prepare twenty questions covering recycling, biodiversity, water conservation, climate change, forests, wildlife, and pollution. Verify every answer using reliable environmental education sources. Divide participants into teams and explain the correct answers after each round. Include practical questions about everyday habits rather than relying entirely on memorisation. Encourage participants to suggest one environmentally responsible action they can adopt after the quiz. Record which topics generated the most discussion and prepare additional educational material about them. Use the activity to make environmental learning interesting, interactive, and accessible to different age groups.`,

  `Create a school or household campaign against food packaging waste. Research which food items are commonly sold in unnecessary disposable packaging. Encourage people to choose suitable products with minimal packaging when affordable and available. Promote reusable lunch boxes, food containers, and shopping bags. Explain the importance of maintaining food hygiene and avoiding unsafe storage practices. Create an informative display showing common alternatives to disposable packaging. Ask participants to share ideas for reducing packaging without wasting food or increasing costs. Monitor the campaign for one week and document changes in purchasing habits and packaging waste.`,

  `Study the importance of protecting mountain ecosystems. Research how mountains influence weather patterns, store freshwater, and provide habitats for specialised plant and animal species. Learn about threats such as deforestation, unsustainable tourism, mining, pollution, and climate change. Create a poster illustrating the connections between mountain forests, rivers, wildlife, and nearby communities. Explain why visitors should remain on designated paths, carry their waste back, and respect local conservation rules. Include examples of protected mountain areas from your country. Share your findings with others and encourage responsible tourism that respects the natural environment and local communities.`,

  `Create a household recycling information board. Research the materials accepted by your local recycling programme, including suitable paper, cardboard, metal, glass, and specific plastics. Clearly explain that recycling rules vary between locations and that contaminated materials may not be accepted. Include instructions for keeping recyclables clean and dry when required. Add separate information about batteries, electronic waste, and other materials needing specialised disposal. Place the board somewhere visible in your home. Encourage everyone to check the instructions before throwing items away. Review the board periodically and update it whenever local waste collection rules change.`,

  `Start a small balcony gardening project using environmentally responsible methods. Select plants suited to your available sunlight, space, and climate. Reuse suitable containers, ensure proper drainage, and choose appropriate growing material. Consider native flowering plants, herbs, or vegetables that can grow safely in containers. Water according to each plant's needs and avoid wasting resources. Observe insects and pollinators that visit the plants. Do not use harmful chemicals unnecessarily. Record plant growth, watering requirements, and seasonal changes in a gardening notebook. Share your experience with neighbours to demonstrate how even small urban spaces can support greenery and biodiversity.`,

  `Research the role of bees in maintaining healthy ecosystems. Learn how different bee species pollinate flowering plants and contribute to food production and biodiversity. Investigate threats including habitat loss, pesticide exposure, diseases, and changing climate conditions. Prepare an educational poster explaining why bees should be respected rather than unnecessarily disturbed. Suggest practical actions such as growing native flowering plants, protecting nesting habitats, and reducing harmful pesticide use. Avoid approaching or handling unfamiliar bee colonies. Present your findings in a classroom or community setting and explain why pollinator conservation is important for natural ecosystems and agricultural communities.`,

  `Prepare a community guide about responsible disposal of household batteries. Research why used batteries should not be placed in ordinary rubbish where specialised collection is available. Explain that certain batteries can create fire and environmental risks when damaged or improperly handled. Identify official collection points or authorised recycling programmes in your area. Encourage families to keep batteries in appropriate temporary storage according to local safety instructions until disposal. Never dismantle, puncture, or experiment with batteries. Design a simple poster explaining where residents can obtain accurate disposal information. Share the guide through an appropriate community channel to improve awareness of electronic waste management.`,

  `Create an educational project about protecting sea turtles. Research the life cycle, nesting behaviour, diet, and migration patterns of sea turtles. Learn about threats such as plastic pollution, habitat disturbance, accidental capture, and illegal wildlife trade. Explain why nesting beaches and healthy marine ecosystems are important for their survival. Create an illustrated presentation using trustworthy wildlife conservation information. Suggest ways people can help, including keeping beaches clean, reducing plastic waste, and respecting protected nesting areas. Do not approach turtles or disturb nests. Share your project with friends and encourage responsible behaviour around coastal environments.`,

  `Explore the importance of protecting urban trees. Identify trees growing along nearby streets, in public gardens, or around educational institutions. Research how urban trees provide shade, improve local habitats, support birds and insects, and help manage rainwater. Observe whether any trees appear damaged or surrounded by unsuitable construction activity. Report serious concerns to the responsible authorities instead of attempting repairs yourself. Prepare an awareness poster explaining why healthy mature trees are valuable community assets. Encourage residents to protect existing trees and support suitable native planting programmes. Include reminders that newly planted trees require long-term care and maintenance.`,

  `Conduct a household natural resource awareness challenge. For seven days, record your family's approximate use of electricity, water, food, paper, and disposable packaging. Identify the resources that are most frequently wasted and discuss practical ways to reduce unnecessary consumption. Avoid making comparisons that shame individual family members. Instead, create shared goals that everyone can realistically follow. Examples include planning meals, using natural daylight, and repairing small leaks. Review your records at the end of the week and prepare a short summary of improvements. Explain how responsible resource consumption supports environmental sustainability and helps reduce pressure on natural ecosystems.`,

  `Create a campaign encouraging people to protect local lakes. Research the plants, animals, and communities that depend on nearby freshwater ecosystems. Identify possible pollution sources such as litter, sewage, chemical runoff, and excessive nutrient discharge. Create a simple information sheet explaining why lake water quality matters for biodiversity and community wellbeing. Encourage residents to avoid dumping waste into drains and waterways. Find official channels for reporting visible pollution. Never enter unsafe water or attempt to remove hazardous materials. Share your campaign through a school or community display and promote long-term protection of freshwater habitats.`,

  `Learn about sustainable agriculture and its environmental benefits. Research farming practices such as crop rotation, soil conservation, integrated pest management, water-efficient irrigation, and maintaining biodiversity around farms. Explain how these methods can support soil health and reduce unnecessary resource consumption. Create an illustrated comparison between responsible farming practices and environmentally damaging activities. Use trustworthy agricultural and scientific information. Include examples relevant to your region where available. Present your findings to classmates or family members. Encourage people to appreciate the relationship between healthy ecosystems, responsible food production, and the long-term sustainability of agricultural communities.`,

  `Prepare an awareness campaign about reducing household chemical pollution. Research how certain cleaning products, paints, oils, and chemicals can contaminate soil and water when disposed of incorrectly. Read product labels and follow official disposal instructions. Encourage families to use suitable quantities of household cleaning products rather than applying excessive amounts. Never mix chemicals or pour hazardous substances into drains or outdoor areas. Create an information sheet explaining why local disposal rules matter. Identify authorised collection services for relevant materials. Share your findings with family members and emphasise that responsible chemical management helps protect waterways, wildlife, and community environments.`,

  `Organise a nature observation journal challenge. Spend ten minutes each day observing a nearby natural space such as a garden, park, or tree-lined street. Record weather conditions, plant growth, visiting insects, birds, and other visible changes. Avoid disturbing wildlife or collecting natural materials. Use sketches and photographs to make your journal interesting. At the end of seven days, compare your observations and identify patterns in animal activity or plant development. Research any unfamiliar species using reliable sources. Share selected discoveries with friends and explain how regular observation can increase environmental awareness and appreciation for biodiversity in everyday surroundings.`,

  `Create a campaign to encourage responsible tourism. Research how tourism can affect forests, beaches, mountains, wildlife habitats, and local communities. Explain why visitors should follow designated trails, avoid feeding wild animals, respect protected areas, and take their rubbish home. Include advice about supporting local conservation initiatives and choosing responsible tourism operators. Create a short digital guide featuring practical travel habits that minimise environmental disturbance. Share it with friends or family before their next trip. Emphasise that enjoying natural destinations should never involve damaging habitats or disturbing wildlife for photographs and entertainment.`,

  `Research how climate change affects biodiversity. Learn how changing temperatures, rainfall patterns, ocean conditions, and extreme weather events can influence different plant and animal species. Find examples of species or ecosystems experiencing climate-related pressures. Explain why habitat protection, ecosystem restoration, and reducing greenhouse gas emissions are important responses. Prepare a short presentation using reliable scientific information and clearly identified sources. Avoid exaggerating statistics or presenting uncertain predictions as guaranteed outcomes. Share your findings with classmates and encourage discussions about practical climate action. Highlight how protecting healthy ecosystems can also improve resilience to environmental changes.`,

  `Start a household reusable container system. Identify suitable clean containers already available in your home that can safely store food, stationery, or other household materials. Label containers where necessary and establish convenient storage locations. Encourage family members to use them instead of repeatedly purchasing disposable storage products. Make sure containers are appropriate for their intended use and maintained hygienically. Avoid buying large quantities of new products when existing items work perfectly well. Record examples of disposable packaging avoided during the week. Explain how extending the useful life of everyday objects supports waste reduction and more responsible resource consumption.`,

  `Prepare a poster about protecting amphibians such as frogs and toads. Research their role in ecosystems, including insect population regulation and their importance as indicators of environmental conditions. Learn about threats such as habitat destruction, water pollution, disease, and changing climate conditions. Explain why ponds, wetlands, and suitable vegetation are important for amphibian survival. Create original illustrations showing amphibians in healthy natural habitats. Encourage people to avoid introducing pollutants into waterways and to protect local wetlands. Share your poster with classmates or family members and explain why even small animals play important ecological roles.`,

  `Investigate how excessive light pollution affects the natural environment. Research how artificial lighting at night can interfere with the behaviour of insects, birds, turtles, and other wildlife. Explain how unnecessary outdoor lighting also wastes electricity and reduces visibility of the night sky. Observe lighting around your home and identify places where lights are unnecessarily bright or switched on. Suggest practical solutions such as using suitable downward-facing lights and switching off unused outdoor lighting. Discuss safety requirements with responsible adults before changing any lighting arrangements. Prepare an awareness poster encouraging thoughtful lighting choices that protect both wildlife and people.`,

  `Create a small community seed-sharing project using suitable native plant seeds. Research which native species are appropriate for your region and whether their seeds can be legally and responsibly shared. Obtain seeds from reliable sources rather than collecting protected or threatened plants from the wild. Prepare clearly labelled packets with basic planting instructions and ecological information. Encourage participants to grow locally suitable plants in appropriate spaces. Explain why native vegetation can support local wildlife and biodiversity. Track how many packets are shared and gather feedback about successful planting. Make sure participants understand that different plants require different growing conditions and care.`,

  `Prepare an environmental awareness activity focused on protecting forests from fires. Research common causes of forest fires and their consequences for wildlife, vegetation, soil, and nearby communities. Explain the importance of following official fire prevention rules when visiting natural areas. Encourage visitors never to leave burning materials or rubbish behind. Share information about reporting smoke or suspected fires through authorised emergency channels. Do not attempt to approach or fight a wildfire. Create an informative poster showing how responsible behaviour can reduce accidental fire risks. Emphasise that prevention, awareness, and following official instructions are essential for protecting forest ecosystems.`,

  `Develop a household plan for reducing unnecessary water use while gardening. Research the watering needs of plants commonly grown in your region. Consider watering at suitable times to reduce evaporation and using mulch where appropriate. Group plants with similar water requirements and avoid watering areas that do not need it. Explore whether safely collected rainwater can be used for suitable non-drinking purposes. Check containers and hoses for leaks with adult assistance. Keep a weekly gardening water diary and record observations about plant health. Explain how water-efficient gardening can maintain healthy plants while reducing pressure on freshwater resources.`,

  `Research the ecological importance of earthworms. Learn how earthworms contribute to soil structure, organic matter decomposition, and nutrient cycling. Investigate the conditions that support healthy earthworm populations, including suitable soil moisture and organic material. Create an illustrated educational sheet showing their role in healthy ecosystems. Explain why unnecessary pesticide use and soil degradation can affect soil organisms. If you observe earthworms in a garden, watch them without handling or disturbing them. Share your findings with classmates or family members and encourage responsible soil management and composting practices that support a diverse community of beneficial soil organisms.`,

  `Create an educational presentation about ocean plastic pollution. Research how plastic waste reaches oceans through rivers, coastal activities, fishing equipment, and poorly managed waste systems. Explain the potential effects of plastic pollution on marine organisms and habitats. Include information about microplastics and why preventing plastic leakage is important. Suggest realistic actions such as reducing unnecessary packaging, disposing of waste correctly, and supporting effective waste management systems. Use trustworthy scientific sources and avoid unsupported claims. Present your findings to friends or classmates. Encourage participants to recognise that ocean conservation begins with responsible decisions made in communities far from the coastline.`,

  `Organise a school gardening awareness project. Identify an appropriate space where a small garden could be created with permission. Research native flowers, herbs, or vegetables that suit the available sunlight, soil, and climate. Prepare a simple planting plan and estimate the water and maintenance required. Invite interested students to help with safe gardening activities under suitable supervision. Explain how gardens can provide learning opportunities about pollination, soil, plant growth, and biodiversity. Keep a progress journal with photographs and observations. Encourage students to take responsibility for maintaining the garden rather than treating planting as a one-day activity.`,

  `Investigate the environmental impact of fast fashion. Research how rapidly changing clothing trends can encourage overproduction, textile waste, and excessive consumption of resources. Learn about the environmental challenges associated with fabric production, dyeing, transportation, and disposal. Examine ways to extend the useful life of clothing through repairing, reusing, sharing, and responsible donation. Create a presentation explaining the difference between buying something necessary and purchasing something only because it is trending. Encourage thoughtful shopping without judging anyone's clothing choices. Share practical ideas that help reduce textile waste and promote more sustainable clothing habits.`,

  `Prepare a local biodiversity map. Select a nearby public green space or suitable neighbourhood area and identify locations where different plants, birds, insects, and other organisms can be observed. Use publicly available maps and your own observations to mark important natural features. Do not enter private property or protected areas without permission. Add short descriptions of habitats such as gardens, ponds, tree clusters, and flowering spaces. Explain how these features support local wildlife. Present the map to classmates or community members and encourage them to observe nature responsibly. Update the map as you discover additional species and habitats.`,

  `Create a household waste reduction calendar. Assign one small environmental improvement to each day for a week. Examples include checking for unnecessary electricity use, avoiding disposable bags, planning meals, sorting recyclables, and reusing suitable containers. Make each activity achievable for everyone in your household. Add simple reminders and explanations so participants understand why each action matters. Record which activities were completed and which require further planning. At the end of the week, discuss which improvements should become permanent habits. Turn the calendar into a reusable monthly activity and encourage family members to contribute their own practical ideas.`,

  `Research the importance of protecting riverside vegetation. Learn how trees, grasses, and shrubs growing near rivers can help stabilise soil, provide wildlife habitat, and reduce certain forms of runoff. Investigate threats such as construction, vegetation removal, pollution, and invasive plants. Create an educational diagram showing how riverbank vegetation supports healthy freshwater ecosystems. If possible, observe a safe public riverside location without disturbing the habitat. Record visible plants and wildlife from an appropriate distance. Share your findings with others and explain why maintaining natural vegetation along waterways is an important part of freshwater conservation.`,

  `Develop an environmental awareness campaign about responsible pet ownership and wildlife protection. Research how abandoned pets, uncontrolled roaming animals, and the release of non-native species can affect local ecosystems. Explain why pets should receive appropriate care and should not be abandoned in natural habitats. Encourage families to follow local rules about pet supervision and responsible waste disposal. Include guidance about never releasing aquarium animals or unwanted pets into ponds and rivers. Create a clear information poster using reliable animal welfare sources. Emphasise that caring for domestic animals and protecting native wildlife are both important responsibilities.`,

  `Create a project explaining how forests help maintain the water cycle. Research how trees absorb water, release moisture through transpiration, intercept rainfall, and influence soil conditions. Prepare a labelled diagram showing connections between forests, clouds, rainfall, rivers, and groundwater. Explain how deforestation can alter local environmental conditions and increase soil erosion. Include examples from forest ecosystems in your country. Use accurate educational resources and avoid presenting simplified diagrams as complete scientific explanations. Share your project with classmates or family members and encourage appreciation for the important connections between forests and freshwater resources.`,

  `Conduct a responsible packaging comparison at home. Choose five commonly purchased household products and examine the packaging they use. Research whether reusable, refillable, recyclable, or less-packaged alternatives are available locally. Compare options based on practicality, affordability, durability, and local disposal facilities rather than assuming every alternative is automatically better. Record your findings in a simple table. Discuss the results with your family and select one realistic improvement to try during the next shopping trip. Explain how informed purchasing decisions can reduce unnecessary packaging while respecting household budgets and everyday requirements.`,

  `Prepare a presentation about the environmental importance of mangrove wildlife. Research the fish, crabs, birds, insects, and other organisms that depend on mangrove ecosystems. Explain how mangrove roots create shelter and support food webs in coastal environments. Investigate how pollution, coastal development, and habitat destruction threaten these species. Create a colourful food web diagram showing relationships between different organisms. Include reliable examples from coastal regions in your country. Share your findings with classmates and encourage them to understand why protecting mangroves benefits both wildlife and nearby coastal communities.`,

  `Start a neighbourhood tree observation project. Select a few accessible trees in a public area where observation is permitted. Record their approximate height, leaf shape, bark appearance, and seasonal changes without damaging them. Research their species using reliable botanical references. Observe whether birds, insects, or other organisms use the trees as habitats. Take photographs from the same locations every few weeks to document changes. Avoid climbing trees or disturbing wildlife. Prepare a short report explaining the ecological benefits of mature trees and why protecting existing urban greenery should be an important community priority.`,

  `Create a guide about responsible disposal of used cooking oil. Research why pouring large quantities of cooking oil into drains can create plumbing and wastewater management problems. Investigate local collection or disposal instructions for used cooking oil. Encourage households to allow oil to cool and store it safely in an appropriate sealed container until it can be handled according to local guidance. Never pour hot oil into containers or handle it carelessly. Prepare a simple awareness poster explaining better disposal habits. Share the information with family members and neighbours to encourage cleaner drains and more responsible household waste management.`,

  `Explore how invasive species can affect native ecosystems. Research examples of non-native organisms that have become invasive in different parts of your country or the world. Explain how some introduced species can compete with native organisms, alter habitats, or disrupt food webs. Emphasise that not every non-native species is invasive and that ecological impacts depend on the situation. Create an educational presentation with verified examples and photographs. Suggest responsible actions such as avoiding the release of unwanted pets and following official guidance about invasive species reporting. Encourage people to support science-based biodiversity protection efforts.`,

  `Organise a community awareness day about reducing food waste. Prepare simple information sheets showing how meal planning, sensible shopping, proper storage, and using suitable leftovers can prevent unnecessary waste. Invite family members, classmates, or neighbours to contribute practical tips. Explain how discarded food represents wasted resources, including water, land, energy, and transportation. Include guidance about food safety and avoiding consumption of spoiled items. If a suitable local food donation organisation exists, share its verified donation requirements. Record the ideas participants find most useful and prepare a follow-up message encouraging continued responsible food management.`,

  `Research the importance of protecting desert ecosystems. Learn how desert plants and animals survive in environments with limited rainfall and extreme temperature differences. Investigate the ecological importance of specialised adaptations and the threats caused by habitat destruction, pollution, mining, and unsustainable tourism. Create a visual guide featuring native desert species and their adaptations. Explain why desert environments should not be considered empty or lifeless. Use reliable scientific sources and include examples from desert regions in your country. Share your findings with classmates and encourage respect for fragile arid ecosystems.`,

  `Create an environmental awareness campaign about sustainable fishing. Research how overfishing, destructive fishing methods, bycatch, and habitat damage can affect marine and freshwater populations. Explain why healthy fish populations are important for aquatic food webs and communities that depend on fishing. Learn about responsible fishing regulations and sustainable seafood guidance from reliable organisations. Prepare a presentation describing the importance of protecting breeding habitats and following catch limits. Avoid making unsupported claims about individual seafood products. Encourage people to learn where their seafood comes from and support responsible fisheries whenever suitable options are available.`,

  `Develop a household plan to reduce unnecessary paper towels and tissues. Observe where disposable paper products are commonly used for cleaning and drying. Identify appropriate situations where clean, reusable cloths could safely replace disposable alternatives. Create a collection of washable cloths and establish a proper washing and drying routine. Maintain separate cloths for different cleaning purposes to support hygiene. Explain why reducing unnecessary disposable paper use can save resources when reusable alternatives are used responsibly. Record how many disposable sheets your household avoids over one week and discuss whether the change is practical for everyone.`,

  `Prepare a school presentation about protecting wildlife corridors. Research how natural corridors allow animals to move between habitats in search of food, shelter, and breeding areas. Explain how roads, buildings, fences, and habitat fragmentation can interrupt these movements. Include examples of wildlife corridors or crossing structures from reliable conservation sources. Create a simple map showing how connected habitats can support biodiversity. Discuss why careful urban planning and habitat restoration are important for wildlife. Present your findings to classmates and encourage awareness of how human infrastructure can be designed to reduce ecological disruption.`,

  `Create a personal climate-friendly cooking challenge. For one week, plan meals that make sensible use of available ingredients and reduce unnecessary food waste. Explore locally available seasonal foods and plant-based meal options if suitable for your dietary needs. Avoid purchasing ingredients that are unlikely to be used. Use appropriate cooking methods and switch off appliances safely when finished. Keep food stored at safe temperatures and never compromise food hygiene. Record the meals you prepare and any ingredients successfully reused. Reflect on how thoughtful meal planning can reduce waste and encourage more responsible use of household resources.`,

  `Research how plastic pollution affects freshwater animals. Learn about the ways plastic bags, packaging, fishing materials, and small plastic fragments can enter rivers, lakes, and ponds. Investigate possible impacts on fish, turtles, birds, and other freshwater organisms. Prepare an illustrated information sheet showing how waste moves through waterways. Suggest preventive measures such as responsible waste disposal, improved collection systems, and avoiding unnecessary single-use plastics. Use reliable scientific sources and avoid exaggerated claims. Share your findings with classmates or family members and explain why protecting freshwater environments is essential for biodiversity.`,

  `Create an awareness campaign about preserving old trees. Research how mature trees can provide nesting spaces, shelter, food, and microhabitats for many organisms. Explain why newly planted trees cannot immediately replace all the ecological benefits of established trees. Observe mature trees in accessible public spaces and record the wildlife you notice. Encourage communities to support responsible tree protection and proper urban planning. If you notice possible damage or unauthorised removal, report it through appropriate official channels. Prepare an educational poster showing why protecting existing trees should accompany efforts to plant new ones.`,

  `Explore the environmental benefits of repairing household objects. Select five everyday items that could potentially be repaired instead of immediately replaced. Research safe repair options for simple objects such as clothing, stationery, furniture, or household accessories. Never attempt repairs involving dangerous electrical components or tools without qualified adult assistance. Estimate how extending the useful life of products can reduce waste and demand for new materials. Create a repair awareness chart showing examples of objects that can be maintained or reused. Encourage family members to consider repair options before purchasing replacements whenever doing so is safe and economical.`,

  `Prepare a guide to protecting nesting birds during breeding seasons. Research why birds need suitable nesting habitats and how excessive disturbance can affect their breeding behaviour. Explain why people should avoid approaching nests, touching eggs, trimming occupied nesting vegetation, or disturbing young birds. Encourage residents to maintain suitable native vegetation and keep pets under responsible supervision. Include information about contacting local wildlife authorities when assistance is needed. Create an informative poster with illustrations of bird-friendly spaces. Share your guide with classmates or neighbours and promote respectful observation of nesting wildlife throughout the year.`,

  `Investigate the environmental importance of seagrass meadows. Research how seagrass provides shelter and food for marine organisms, stabilises sediment, and stores carbon. Learn about threats such as coastal development, pollution, anchoring damage, and changing ocean conditions. Prepare an illustrated presentation showing the difference between seagrass and seaweed. Include examples of seagrass habitats and animals that depend on them. Use trustworthy marine science resources. Share your findings with others and explain why underwater habitats deserve conservation attention just as much as forests, coral reefs, and other familiar ecosystems.`,

  `Organise a community campaign encouraging proper disposal of used clothing. Research local textile donation, reuse, and recycling options. Explain why clean, wearable clothing should be donated responsibly rather than automatically thrown away. Identify organisations that accept specific items and check their requirements before recommending donations. Discuss alternatives such as clothing exchanges, repairs, and creative reuse of unsuitable fabrics where practical. Prepare clear instructions so residents understand what can and cannot be accepted. Share your campaign through a community noticeboard or school group and encourage people to extend the useful life of clothing and reduce textile waste.`,

  `Create an educational display explaining the importance of biodiversity in food production. Research how pollinators, soil organisms, birds, and other wildlife contribute to healthy agricultural ecosystems. Explain why genetic diversity in crops and the presence of beneficial organisms can support food system resilience. Include examples of ecosystem services such as pollination and natural pest regulation. Prepare a simple diagram showing connections between farms and surrounding natural habitats. Use reliable scientific information and explain technical terms clearly. Share your display with classmates or family members and encourage appreciation of the relationship between biodiversity and sustainable agriculture.`,

  `Start a week-long household challenge to reduce unnecessary electricity consumption. Encourage family members to switch off unused lights and appliances, use natural daylight where possible, and avoid leaving electronics running unnecessarily. Research safe energy-saving settings for household devices. Do not switch off essential equipment or interfere with electrical installations. Record simple observations about which habits are easiest to follow. If accessible, compare household electricity readings over a suitable period while considering other factors that affect consumption. Create a final summary describing improvements and encouraging continued energy-conscious behaviour.`,

  `Research the importance of protecting island ecosystems. Learn why islands often contain unique species that may exist nowhere else. Investigate threats such as invasive species, habitat loss, pollution, and rising sea levels. Prepare an educational map featuring selected islands and examples of their distinctive wildlife. Explain why introducing non-native plants or animals can create serious ecological problems. Include practical conservation measures such as habitat protection, responsible tourism, and biosecurity awareness. Share your project with classmates and encourage appreciation of the special biodiversity found in island environments.`,

  `Create a responsible gardening guide focused on avoiding unnecessary pesticides. Research how excessive pesticide use can affect pollinators, soil organisms, aquatic environments, and other wildlife. Learn about alternative approaches such as choosing suitable plants, maintaining healthy soil, removing weeds appropriately, and encouraging natural predators. Explain that pest management should be based on accurate identification rather than automatically applying chemicals. Include advice to follow product labels and seek qualified guidance whenever necessary. Prepare a poster showing how healthy gardens can support biodiversity. Encourage gardeners to protect beneficial organisms while managing genuine plant health problems responsibly.`,

  `Develop a nature-based learning activity for younger students. Design a simple outdoor observation game where participants identify leaf shapes, notice different flower colours, listen for bird calls, and observe insects from a respectful distance. Make sure activities take place in a safe, permitted environment with suitable adult supervision. Do not encourage collecting wildlife, damaging plants, or approaching unfamiliar animals. Prepare a worksheet with spaces for drawings and observations. Explain the ecological importance of a few organisms discovered during the activity. Encourage younger participants to develop curiosity, respect for living things, and appreciation for the natural world.`,

  `Prepare an awareness project about protecting polar ecosystems. Research the Arctic and Antarctic environments and learn about their specialised wildlife, ice systems, and food webs. Investigate how global warming affects sea ice, ocean conditions, and species that depend on cold habitats. Explain the differences between the Arctic and Antarctic rather than treating them as identical ecosystems. Create a labelled comparison chart using trustworthy scientific sources. Include examples of conservation research and climate action. Share your project with classmates and explain why environmental changes in polar regions can have effects far beyond the polar areas themselves.`,

  `Create a community guide explaining how to report environmental pollution. Research the official local authorities responsible for handling concerns about illegal dumping, water pollution, air pollution, and damage to protected green spaces. Record verified reporting channels and explain what information may be useful, such as the location, date, and nature of the observation. Never confront suspected offenders or enter dangerous areas to collect evidence. Prepare a clear guide that helps residents report concerns safely and responsibly. Share it through an appropriate community channel and encourage people to support environmental protection through lawful reporting.`,

  `Investigate the environmental impact of unnecessary online shopping deliveries. Research how packaging, transportation, returns, and product manufacturing contribute to environmental resource use. Examine whether household purchases can be combined into fewer deliveries when convenient. Encourage thoughtful shopping rather than ordering items that are unlikely to be used. Reuse suitable delivery packaging and follow local recycling instructions for materials that cannot be reused. Compare convenience and environmental considerations without assuming every delivery has the same impact. Prepare a short presentation showing how planning purchases can reduce unnecessary packaging and encourage more responsible consumption.`,

  `Create an educational poster about the importance of protecting mangrove seedlings and young trees. Research how mangrove forests regenerate naturally and why young plants need suitable tidal, soil, and water conditions. Explain that mangroves cannot grow successfully in every coastal location. Include information about threats such as trampling, pollution, coastal construction, and habitat disturbance. Use accurate diagrams showing mangrove root systems and coastal habitats. Encourage people to support professionally planned restoration projects rather than planting unsuitable species independently. Share the poster with classmates and explain why successful restoration requires ecological knowledge and long-term monitoring.`,

  `Plan a household challenge to reduce unnecessary water used during cleaning. Observe activities such as washing floors, cleaning outdoor areas, and rinsing household items. Research practical alternatives such as using a bucket instead of continuously running a hose where appropriate. Reuse suitable water only when it is safe for the intended purpose, and never reuse contaminated water around edible plants. Check cleaning requirements and hygiene before making changes. Record the methods your family tries during the week. Prepare a short summary showing how careful planning can reduce freshwater waste without compromising cleanliness or safety.`,

  `Research the environmental importance of native grasses. Learn how native grass species provide habitat and food for insects, birds, and other animals. Investigate how their root systems can help stabilise soil and support water infiltration. Compare native grasslands with landscapes dominated by unsuitable introduced species. Create a visual information sheet showing the ecological value of different grassland habitats. Include locally relevant species where reliable information is available. Encourage residents and gardeners to consider native grasses in suitable landscaping projects. Explain why preserving natural grasslands is important for biodiversity and ecosystem health.`,

  `Create a digital environmental awareness magazine. Include short articles about recycling, wildlife conservation, water saving, tree protection, renewable energy, and reducing plastic waste. Research each topic using reliable sources and provide references for factual claims. Add original illustrations, simple diagrams, and practical tips that readers can follow. Avoid copying articles or photographs without permission. Invite friends or classmates to contribute their own environmental ideas. Organise the magazine into clear sections and share it through an appropriate digital platform. Aim to make environmental knowledge accessible, interesting, and useful for people with different levels of scientific understanding.`,

  `Investigate how renewable energy can help reduce environmental impacts. Research solar, wind, hydroelectric, and other renewable energy sources. Explain how each technology generates electricity and identify some environmental considerations associated with its development and operation. Compare renewable energy with fossil fuel-based electricity using reliable information. Create a simple infographic showing different energy sources and their advantages and limitations. Include examples of renewable energy projects in your country. Share your findings with classmates or family members and encourage informed discussions about clean energy transitions and responsible energy consumption.`,

  `Organise a local nature appreciation walk. Choose a safe public green space and obtain any necessary permissions. Walk slowly and observe trees, plants, insects, birds, soil, and other natural features. Encourage participants to notice small details that are often overlooked. Do not collect flowers, disturb nests, feed wildlife, or leave litter behind. Prepare a simple observation sheet with spaces for drawings and notes. After the walk, discuss the different organisms participants discovered and how they contribute to the ecosystem. Encourage everyone to revisit the area and continue observing seasonal changes responsibly.`,

  `Create a campaign explaining why wildlife should never be kept as unsuitable exotic pets. Research the welfare and conservation problems associated with illegal wildlife trade and irresponsible exotic animal ownership. Explain how capturing wild animals can affect natural populations and why released non-native animals may disrupt ecosystems. Encourage people to learn about responsible pet ownership and follow local wildlife protection laws. Prepare an informative poster featuring examples of native wildlife and its natural habitats. Avoid promoting the purchase or handling of wild animals. Share your campaign with friends or classmates to increase awareness of animal welfare and biodiversity conservation.`,

  `Prepare an environmental action plan for your school or educational institution. Observe current practices related to electricity use, water consumption, waste separation, gardening, and plastic packaging. Identify three improvements that are affordable, safe, and practical. Discuss your suggestions with teachers or responsible staff before proposing changes. Create a simple action plan assigning responsibilities and realistic timelines. Include a way to measure progress, such as counting reusable bottles or monitoring waste separation. Present your proposal respectfully and invite feedback. Focus on achievable improvements that can become lasting institutional habits rather than temporary activities.`,

  `Research the ecological importance of bats. Learn how different bat species contribute to ecosystems through insect consumption, pollination, and seed dispersal. Investigate common threats such as habitat destruction, disturbance of roosting sites, and harmful misconceptions. Prepare an educational poster explaining why bats are valuable wildlife rather than dangerous pests. Encourage people not to disturb roosting colonies and to seek qualified wildlife assistance when bats enter unsuitable locations. Include examples of bat species found in your region where reliable information exists. Share your findings with classmates and promote respectful coexistence with native wildlife.`,

  `Create a campaign promoting responsible use of natural resources. Research how everyday products depend on materials such as timber, metals, water, minerals, and fossil fuels. Explain why extracting and processing resources can affect habitats, energy consumption, and pollution levels. Encourage people to repair, reuse, share, and recycle suitable products whenever practical. Prepare an illustrated guide showing how a product's life cycle extends beyond its purchase. Use examples from common household items. Share your guide with family members and discuss how thoughtful consumption can reduce unnecessary demand for raw materials and help conserve natural ecosystems.`,

  `Investigate the role of community gardens in environmental conservation. Research how shared gardens can support urban greenery, pollinators, soil health, and local food education. Identify a suitable public or community space where gardening activities may be permitted. Create a proposal describing appropriate native plants, composting options, water management, and maintenance responsibilities. Consider accessibility, safety, and the needs of local residents. Discuss your proposal with relevant community members before beginning any activity. Explain how community gardens can create opportunities for people to learn about nature while improving shared outdoor spaces.`,

  `Prepare an educational activity about protecting river dolphins and other freshwater wildlife. Research species found in major river systems and investigate threats such as pollution, habitat fragmentation, accidental capture, and changes in water flow. Explain why healthy rivers require clean water, suitable habitats, and responsible human activities. Create a labelled map showing selected freshwater wildlife habitats and conservation areas using reliable sources. Include practical actions such as reducing plastic pollution and supporting river protection programmes. Share your activity with classmates and encourage appreciation of the remarkable biodiversity found in freshwater ecosystems.`,

  `Start a monthly environmental progress journal. At the beginning of each month, select three realistic goals related to nature protection, such as reducing household waste, growing suitable native plants, or conserving electricity. Record the actions you take and any difficulties you encounter. Include photographs, drawings, and short reflections. Avoid focusing only on the number of activities completed; consider whether your habits are becoming consistent and sustainable. At the end of the month, review your progress and choose new goals based on what you learned. Use the journal to build long-term environmental awareness and encourage responsible everyday behaviour.`,

  `Create an awareness campaign about protecting natural springs. Research how springs provide freshwater habitats and support nearby communities, plants, and animals. Investigate possible threats including groundwater pollution, excessive extraction, construction, and improper waste disposal. Prepare a diagram explaining the relationship between groundwater and surface water. Encourage residents to keep surrounding areas clean and follow local water protection rules. Include information about reporting contamination through official channels. Never drink water from an untested natural source. Share your campaign with classmates or community members and explain why protecting freshwater sources is essential for healthy ecosystems.`,

  `Design a small environmental board game for your family or classmates. Create a game board featuring situations involving recycling, wildlife protection, water conservation, pollution prevention, and sustainable transportation. Players should earn points for choosing environmentally responsible actions and learn from less suitable choices. Include accurate explanations for every environmental question. Make the game enjoyable without presenting complicated environmental problems as having instant solutions. Use reusable cardboard or other suitable materials when creating the board. Test the game with a small group and improve unclear instructions. Use the activity to make environmental education interactive and memorable.`,

  `Research the importance of protecting native fish species. Learn about freshwater and marine fish found in your region and the habitats they require. Investigate threats such as pollution, habitat destruction, invasive species, and unsustainable fishing. Create an illustrated information sheet showing selected fish species and their ecological roles. Explain why maintaining healthy rivers, lakes, wetlands, and coastal habitats is important for fish populations. Use reliable conservation resources and avoid encouraging the capture of wild fish. Share your findings with classmates and promote responsible behaviour around aquatic environments.`,

  `Organise a responsible recycling awareness week at home. Choose a different material category each day, such as paper, cardboard, glass, metal, plastic, and electronic waste. Research the local disposal rules for each category and prepare clear instructions. Explain that materials should be sorted according to the facilities available in your area. Encourage everyone to reuse suitable objects before recycling them. Keep hazardous materials separate and follow official disposal guidance. At the end of the week, review the household's recycling habits and identify areas needing improvement. Share your findings with family members and encourage consistent waste management.`,

  `Create a campaign to protect native flowering plants. Research why locally adapted flowers provide food and habitat for pollinators and other wildlife. Identify species that are suitable for gardens, balconies, or community spaces in your region. Explain why removing native plants from wild habitats is not appropriate. Encourage people to obtain seeds or plants from responsible sources. Prepare an illustrated planting guide with information about sunlight, soil, and watering needs. Share the guide with neighbours or classmates and invite them to observe visiting pollinators. Emphasise that native plants can support biodiversity when grown in suitable environments.`,

  `Prepare a research project about the environmental impact of mining. Learn how mineral extraction can affect land, vegetation, water resources, wildlife habitats, and nearby communities. Investigate how responsible regulation, environmental assessment, pollution control, and site restoration can reduce some impacts. Create a balanced presentation explaining both the importance of minerals in modern life and the environmental responsibilities associated with extraction. Use reliable scientific and governmental sources. Avoid making unsupported claims about specific mining operations. Share your findings with classmates and encourage informed discussions about resource use, responsible production, and environmental protection.`,

  `Develop a plan for making your neighbourhood more wildlife-friendly. Observe existing green spaces, trees, gardens, and potential habitats without entering private property. Identify opportunities for native flowering plants, safe water sources, and better protection of existing vegetation. Research which local species might benefit from these improvements. Discuss your ideas with responsible community members before making changes to shared spaces. Avoid introducing unfamiliar plants or feeding wild animals. Create a simple proposal with photographs, drawings, and maintenance suggestions. Explain how small improvements across many gardens and public spaces can collectively support urban biodiversity.`,

  `Create an awareness campaign about the importance of protecting natural caves. Research how caves provide habitats for specialised organisms and preserve geological formations. Learn about threats such as littering, vandalism, unsuitable tourism, and disturbance of roosting wildlife. Explain why visitors should follow official rules and avoid touching fragile cave formations. Prepare a poster showing responsible behaviour in cave environments. Include information about bats and other cave-dependent species using reliable sources. Encourage people to support protected natural areas and responsible tourism. Emphasise that caves are sensitive ecosystems that can take extremely long periods to develop.`,

  `Research the environmental importance of protecting groundwater. Learn how groundwater supplies wells, springs, wetlands, and other freshwater systems. Investigate how excessive extraction and contamination can affect water availability and ecosystem health. Create a labelled diagram showing how rainwater can infiltrate soil and recharge underground aquifers. Explain why chemicals, untreated waste, and careless disposal practices can threaten groundwater quality. Prepare a short educational presentation using reliable water resource information. Encourage household members to conserve water and follow proper waste disposal practices. Share your findings and explain why groundwater protection is essential for long-term freshwater security.`,

  `Organise a campaign encouraging people to reuse school supplies. Ask participants to identify notebooks, folders, stationery, rulers, and other supplies that remain in good condition. Encourage them to organise and reuse these items before purchasing replacements. Create a suitable exchange system where students can share unused supplies with permission and according to school rules. Explain how reusing products can reduce demand for raw materials, packaging, and transportation. Avoid sharing damaged or unhygienic items. Record the number of supplies successfully reused and prepare a short report about how simple resource-sharing activities can support waste reduction.`,

  `Create an environmental awareness presentation about protecting mountain glaciers. Research how glaciers store freshwater and contribute to river systems in many regions. Learn how rising temperatures influence glacier retreat and affect surrounding ecosystems and communities. Prepare diagrams showing how glacier meltwater contributes to downstream water systems. Explain that glacier changes can have complex effects and depend on regional conditions. Use reliable scientific sources and clearly identify the information presented. Share your presentation with classmates and discuss the importance of climate action, freshwater management, and protecting fragile mountain environments.`,

  `Prepare a practical guide to reducing unnecessary household packaging. Observe the packaging associated with groceries, deliveries, personal care products, and household supplies. Identify opportunities to choose refillable products, reusable containers, or items with less packaging when affordable and available. Explain why local recycling facilities and material types matter when evaluating packaging choices. Create a simple comparison chart featuring five common products and possible alternatives. Discuss your findings with your family and choose one change to try. Focus on realistic solutions that reduce waste without encouraging unnecessary purchases or compromising product safety.`,

  `Start a small biodiversity observation project focused on urban insects. Visit a safe garden or public green space and observe butterflies, bees, beetles, ants, and other insects from a respectful distance. Record the plants and habitats where you find them. Avoid touching, catching, or disturbing unfamiliar insects. Research the ecological roles of three observed groups, including pollination, decomposition, and natural pest regulation. Create a short illustrated report using your own observations. Share your findings with classmates and explain why insects are important components of healthy ecosystems. Encourage others to appreciate small organisms rather than overlooking them.`,

  `Design a community campaign encouraging people to protect public parks. Research how parks provide recreation, shade, habitat, and environmental benefits within urban areas. Identify common problems such as littering, damage to trees, pollution, and disturbance of wildlife. Create a poster explaining simple visitor responsibilities, including using waste bins, respecting plants, and keeping noise at appropriate levels. Encourage residents to report maintenance problems through official channels. Do not organise activities in restricted areas without permission. Share your campaign with local community groups and explain why well-maintained green spaces are valuable for people and nature.`,

  `Prepare an educational project about the relationship between forests and wildlife. Select a forest ecosystem and research at least five organisms that depend on it. Explain how trees, shrubs, fungi, insects, birds, and mammals interact through food webs and habitat relationships. Investigate threats such as fragmentation, pollution, illegal hunting, and climate change. Create an illustrated ecosystem diagram showing these connections. Include examples of conservation programmes using trustworthy sources. Share your project with classmates and emphasise that protecting a forest means protecting the interconnected community of living organisms within it.`,

  `Create a household challenge to reduce disposable cleaning products. Review which cleaning items are regularly used and whether suitable refillable or reusable alternatives exist. Research safe methods for maintaining washable cleaning cloths and reusable containers. Follow product instructions and never mix cleaning chemicals. Encourage family members to purchase only the quantities they need and avoid unnecessary packaging. Record which products were successfully replaced or reused over two weeks. Explain why reducing disposable materials can lower household waste. Include a reminder that hygiene, product safety, and the specific cleaning requirements of different surfaces must always remain important.`,

  `Research the environmental importance of protecting native mammals. Choose three mammal species found in your region and investigate their habitats, diets, and ecological roles. Learn about threats such as habitat fragmentation, pollution, road collisions, and illegal wildlife trade. Create an educational comparison chart explaining how different species contribute to their ecosystems. Use reliable wildlife resources and avoid sharing unverified information about rare animals. Suggest practical conservation actions such as protecting natural habitats and respecting wildlife areas. Present your findings to classmates or family members and encourage responsible coexistence with native wildlife.`,

  `Create a project explaining why wetlands should be included in urban planning. Research how urban wetlands can provide habitat, store water, support biodiversity, and help manage stormwater. Investigate how filling or polluting wetlands can affect nearby communities and ecosystems. Prepare a simple diagram comparing a natural wetland with an area where natural vegetation and water storage have been removed. Include examples of wetland conservation or restoration projects from reliable sources. Share your project with classmates and encourage people to recognise wetlands as important natural infrastructure that deserves protection.`,

  `Organise a family environmental discussion evening. Select five topics such as plastic waste, water conservation, wildlife protection, energy use, and food waste. Prepare a few accurate facts and practical questions for each topic. Invite every family member to suggest realistic environmental improvements. Encourage respectful discussion and avoid criticising anyone's current habits. Choose two actions that everyone agrees are achievable and record them somewhere visible. Review progress after two weeks. Explain how environmental responsibility becomes more effective when people work together and turn awareness into consistent daily behaviour.`,

  `Create an educational campaign about the importance of protecting natural coastlines. Research how beaches, dunes, coastal vegetation, mangroves, and other shoreline habitats support biodiversity and reduce certain coastal risks. Investigate threats such as plastic pollution, erosion, unsuitable construction, and disturbance from tourism. Prepare a diagram showing how different coastal habitats connect. Encourage visitors to respect protected areas, avoid disturbing nesting wildlife, and dispose of rubbish responsibly. Include examples of conservation efforts from reliable sources. Share your campaign with classmates or family members and promote responsible behaviour during visits to coastal environments.`,

  `Prepare a personal environmental commitment statement. Reflect on the environmental habits you currently follow and identify areas where improvement is possible. Select five realistic commitments covering topics such as saving water, reducing plastic, protecting wildlife, managing waste, and conserving electricity. Explain why each commitment matters and describe exactly how you will practise it. Avoid unrealistic promises that cannot be maintained. Place your statement somewhere visible and review it at the end of every month. Record examples of progress and update goals when necessary. Use the exercise to develop a lasting sense of responsibility towards nature and environmental protection.`
];


function home_page() {
    window.location.href = "index.html";
}

function open_protect() {
    sessionStorage.setItem("protect_clicked", "true");
    window.location.href = "protect.html";
}

function open_hacks() {
    sessionStorage.setItem("hacks_clicked", "true");
    window.location.href = "hacks.html";
}

function open_facts() {
    sessionStorage.setItem("facts_clicked", "true");
    window.location.href = "facts.html";
}

function show_enjoyment() {
    fact_num = document.getElementById("fact").value.trim();
    if (fact_num === "") {
        alert("Please enter a fact number.");
        return;
    }
    else if (parseInt(fact_num) <= 0 || parseInt(fact_num) >= 9) {
        alert("Please enter a fact no. from 1 to 8.");
        return;
    }
    else {
    alert(`I also liked the fact no. ${fact_num}!`);
    }
}

function video() {
    sessionStorage.setItem("videos_clicked", "true");
    window.location.href = "video.html";
}

function random_act() {
    window.location.href = "random.html";
}

function random_num() {
    let randomIndex = Math.floor(Math.random() * 100);
    return randomIndex;
}

function show_random() {
    task.innerHTML = natureTasks[random_num()];
    sessionStorage.setItem("random_clicked", "true");
}

function cert() {
    window.location.href = "certificate.html";
}

function get_name() {
    let uName = "warrior";
    let userName = document.getElementById("certName").value.trim();
    if (userName === "") {
        return uName;
    }
    else {
        return userName;
    }
}

function open_cert(name) {
    if (sessionStorage.getItem("protect_clicked") === "true" && sessionStorage.getItem("hacks_clicked") === "true" && sessionStorage.getItem("facts_clicked") === "true" && sessionStorage.getItem("videos_clicked") === "true" && sessionStorage.getItem("random_clicked") === "true") {
        let url = `https://nature-certificate-api.vercel.app/certificate?name=${name}`;
        cert_validity_content.innerHTML = `Congratulations ${name}! You have explored our whole website and have earned a certificate of appreciation. <a href="${url}">Click here</a> to get your certificate.`
    }
    else {
        cert_validity_content.innerHTML = `Sorry ${name}, you have not explored our whole website yet. Please explore all the sections to earn the certificate.`
    }
} 